update app.unit_reference_entries set body = 'K_c=\frac{[\mathrm{C}]^{c}[\mathrm{D}]^{d}}{[\mathrm{A}]^{a}[\mathrm{B}]^{b}}', items = '[{"label": "K_c", "meaning": "equilibrium constant in terms of concentrations (Qc has the same form, using concentrations at any time)"}, {"label": "[\\mathrm{C}]", "meaning": "molar concentration of product C (mol/L)"}, {"label": "c", "meaning": "stoichiometric coefficient of C, used as its exponent"}, {"label": "[\\mathrm{D}]", "meaning": "molar concentration of product D (mol/L)"}, {"label": "d", "meaning": "stoichiometric coefficient of D, used as its exponent"}, {"label": "[\\mathrm{A}]", "meaning": "molar concentration of reactant A (mol/L)"}, {"label": "a", "meaning": "stoichiometric coefficient of A, used as its exponent"}, {"label": "[\\mathrm{B}]", "meaning": "molar concentration of reactant B (mol/L)"}, {"label": "b", "meaning": "stoichiometric coefficient of B, used as its exponent"}]'::jsonb, caution = 'Kc = Qc only at equilibrium. Substances whose concentrations are independent of amount (solids and pure liquids) are not included. For gas-phase reactions, the Kp and Qp form uses partial pressures. Pay attention to whether Kc or Kp is asked for; conversion between them is not assessed.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u7-r9-002'
