update app.unit_reference_entries set body = 'pH = -\log[H_3O^+]', items = '[{"label": "pH", "meaning": "negative base-10 logarithm of the hydronium ion concentration (unitless)"}, {"label": "[H_3O^+]", "meaning": "molar concentration of hydronium ion (mol/L)"}]'::jsonb, caution = 'H+(aq) and H3O+(aq) are used interchangeably; H3O+ is preferred, but H+(aq) is also accepted on the AP Exam.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-001'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.1' and kind = 'formula' and title = 'pH definition' and status = 'published';
update app.unit_reference_entries set body = 'pK_w = 14 = pH + pOH', items = '[{"label": "pK_w", "meaning": "negative base-10 logarithm of K_w; equals 14.0 at 25°C (unitless)"}, {"label": "pH", "meaning": "-log[H3O+] (unitless)"}, {"label": "pOH", "meaning": "-log[OH-] (unitless)"}]'::jsonb, caution = 'This holds at 25°C only. K_w depends on temperature, so pH + pOH and the pH of neutral water differ from 14 and 7.0 at other temperatures.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-002'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.1' and kind = 'formula' and title = 'pKw, pH and pOH at 25°C' and status = 'published';
update app.unit_reference_entries set body = 'pOH = -\log[OH^-]', items = '[{"label": "pOH", "meaning": "negative base-10 logarithm of the hydroxide ion concentration (unitless)"}, {"label": "[OH^-]", "meaning": "molar concentration of hydroxide ion (mol/L)"}]'::jsonb, caution = 'For a strong base, [OH-] gives pOH. Convert to pH (pH = 14 - pOH at 25°C) before reporting pH.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-003'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.1' and kind = 'formula' and title = 'pOH definition' and status = 'published';
update app.unit_reference_entries set body = 'K_w = [H_3O^+][OH^-] = 1.0\times10^{-14}', items = '[{"label": "K_w", "meaning": "equilibrium constant for the autoionization of water (unitless)"}, {"label": "[H_3O^+]", "meaning": "molar concentration of hydronium ion (mol/L)"}, {"label": "[OH^-]", "meaning": "molar concentration of hydroxide ion (mol/L)"}]'::jsonb, caution = 'The value 1.0 × 10^-14 applies at 25°C only. K_w is temperature dependent.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-004'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.1' and kind = 'formula' and title = 'Water autoionization constant, Kw' and status = 'published';
update app.unit_reference_entries set body = 'K_a = \frac{[H_3O^+][A^-]}{[HA]}', items = '[{"label": "K_a", "meaning": "acid ionization (equilibrium) constant of the weak acid (unitless)"}, {"label": "[H_3O^+]", "meaning": "equilibrium molar concentration of hydronium ion (mol/L)"}, {"label": "[A^-]", "meaning": "equilibrium molar concentration of the conjugate base (mol/L)"}, {"label": "[HA]", "meaning": "equilibrium molar concentration of the un-ionized weak acid (mol/L)"}]'::jsonb, caution = 'Concentrations are equilibrium values. For a weak acid, [HA] at equilibrium is nearly the initial acid concentration, since only a small percentage ionizes.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-005'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.3' and kind = 'formula' and title = 'Acid ionization constant, Ka' and status = 'published';
update app.unit_reference_entries set body = 'pK_a = -\log K_a', items = '[{"label": "pK_a", "meaning": "negative base-10 logarithm of the acid ionization constant (unitless)"}, {"label": "K_a", "meaning": "acid ionization constant (unitless)"}]'::jsonb, caution = NULL, source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-007'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.3' and kind = 'formula' and title = 'pKa' and status = 'published';
update app.unit_reference_entries set body = 'pK_b = -\log K_b', items = '[{"label": "pK_b", "meaning": "negative base-10 logarithm of the base ionization constant (unitless)"}, {"label": "K_b", "meaning": "base ionization constant (unitless)"}]'::jsonb, caution = NULL, source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u8-r9-008'
where subject_key = 'ap_chemistry' and owner_topic_code = '8.3' and kind = 'formula' and title = 'pKb' and status = 'published';
update app.unit_reference_entries set body = 'E = E^{\circ} - \frac{RT}{nF}\ln Q', items = '[{"label": "E", "meaning": "cell potential under the actual (nonstandard) conditions (volts)"}, {"label": "E^{\\circ}", "meaning": "standard cell potential, which corresponds to Q = 1 (volts)"}, {"label": "R", "meaning": "gas constant"}, {"label": "T", "meaning": "temperature (kelvin)"}, {"label": "n", "meaning": "moles of electrons transferred in the redox reaction"}, {"label": "F", "meaning": "Faraday constant (charge per mole of electrons)"}, {"label": "Q", "meaning": "reaction quotient for the cell reaction"}]'::jsonb, caution = 'Use it qualitatively: algorithmic Nernst calculations alone are insufficient. Justify with concentration effects and distance from equilibrium (|E| shrinks to zero as Q approaches K). Do not apply Le Châtelier''s principle to the cell.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-001'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.10' and kind = 'formula' and title = 'Nernst equation (qualitative use)' and status = 'published';
update app.unit_reference_entries set body = 'I = \frac{q}{t}', items = '[{"label": "I", "meaning": "current (amperes, i.e. coulombs per second)"}, {"label": "q", "meaning": "charge that flows (coulombs)"}, {"label": "t", "meaning": "time elapsed (seconds)"}]'::jsonb, caution = 'Time must be in seconds when current is in amperes and charge is in coulombs.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-002'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.11' and kind = 'formula' and title = 'Current and charge' and status = 'published';
update app.unit_reference_entries set body = '\Delta S^{\circ}_{reaction} = \Sigma S^{\circ}_{products} - \Sigma S^{\circ}_{reactants}', items = '[{"label": "\\Delta S^{\\circ}_{reaction}", "meaning": "standard entropy change for the process"}, {"label": "\\Sigma", "meaning": "sum over all species on that side of the equation"}, {"label": "S^{\\circ}_{products}", "meaning": "absolute (standard molar) entropies of the products"}, {"label": "S^{\\circ}_{reactants}", "meaning": "absolute (standard molar) entropies of the reactants"}]'::jsonb, caution = 'Each S° is scaled by its stoichiometric coefficient before summing. Products minus reactants.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-003'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.2' and kind = 'formula' and title = 'Standard entropy change of a reaction' and status = 'published';
update app.unit_reference_entries set body = '\Delta G^{\circ} = \Delta H^{\circ} - T\Delta S^{\circ}', items = '[{"label": "\\Delta G^{\\circ}", "meaning": "standard Gibbs free energy change; below 0 means thermodynamically favored"}, {"label": "\\Delta H^{\\circ}", "meaning": "standard enthalpy change"}, {"label": "T", "meaning": "temperature (kelvin)"}, {"label": "\\Delta S^{\\circ}", "meaning": "standard entropy change"}]'::jsonb, caution = 'Use consistent energy units for ΔH° and TΔS°. When arguing favorability, reason from the signs of ΔH° and ΔS° and say which term drives the process; do not claim both help unless both signs support it.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-004'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.3' and kind = 'formula' and title = 'Gibbs free energy equation' and status = 'published';
update app.unit_reference_entries set body = '\Delta G^{\circ}_{reaction} = \Sigma\Delta G_f^{\circ}{}_{products} - \Sigma\Delta G_f^{\circ}{}_{reactants}', items = '[{"label": "\\Delta G^{\\circ}_{reaction}", "meaning": "standard Gibbs free energy change for the process"}, {"label": "\\Sigma", "meaning": "sum over all species on that side of the equation"}, {"label": "\\Delta G_f^{\\circ}{}_{products}", "meaning": "standard Gibbs free energies of formation of the products"}, {"label": "\\Delta G_f^{\\circ}{}_{reactants}", "meaning": "standard Gibbs free energies of formation of the reactants"}]'::jsonb, caution = 'Each ΔGf° is scaled by its stoichiometric coefficient. Products minus reactants. Applies to standard-state conditions.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-005'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.3' and kind = 'formula' and title = 'ΔG° from standard free energies of formation' and status = 'published';
update app.unit_reference_entries set body = 'K = e^{-\Delta G^{\circ}/RT}', items = '[{"label": "K", "meaning": "equilibrium constant"}, {"label": "e", "meaning": "base of the natural logarithm"}, {"label": "\\Delta G^{\\circ}", "meaning": "standard Gibbs free energy change"}, {"label": "R", "meaning": "gas constant"}, {"label": "T", "meaning": "temperature (kelvin)"}]'::jsonb, caution = 'ΔG° and RT must be in the same energy units. ΔG° < 0 gives K > 1 and ΔG° > 0 gives K < 1. When ΔG° is near zero, K is close to 1.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-006'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.5' and kind = 'formula' and title = 'Equilibrium constant from ΔG°' and status = 'published';
update app.unit_reference_entries set body = '\Delta G^{\circ} = -RT\ln K', items = '[{"label": "\\Delta G^{\\circ}", "meaning": "standard Gibbs free energy change"}, {"label": "R", "meaning": "gas constant"}, {"label": "T", "meaning": "temperature (kelvin)"}, {"label": "K", "meaning": "equilibrium constant"}]'::jsonb, caution = 'The sign is negative: K > 1 corresponds to ΔG° < 0 (products favored at equilibrium under standard conditions).', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-007'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.5' and kind = 'formula' and title = 'ΔG° from the equilibrium constant' and status = 'published';
update app.unit_reference_entries set body = '\Delta G^{\circ} = -nFE^{\circ}', items = '[{"label": "\\Delta G^{\\circ}", "meaning": "standard Gibbs free energy change of the cell reaction"}, {"label": "n", "meaning": "moles of electrons transferred in the redox reaction"}, {"label": "F", "meaning": "Faraday constant (charge per mole of electrons)"}, {"label": "E^{\\circ}", "meaning": "standard cell potential (volts)"}]'::jsonb, caution = 'ΔG° is proportional to the negative of E°. Positive E° means thermodynamically favored (galvanic) and negative E° means unfavored (needs an applied potential). Keep the units of F and E° consistent with ΔG°.', source_note = source_note || '; fmt=task0067-chem-formula-symbols-2026-10-10:ap_chemistry-u9-r9-008'
where subject_key = 'ap_chemistry' and owner_topic_code = '9.9' and kind = 'formula' and title = 'Free energy and standard cell potential' and status = 'published';
commit;
